import { TrnscTypeCd } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';

export const getExchangeTransactionLabel = (trnscTypeCd: TrnscTypeCd) => {
  switch (trnscTypeCd) {
    case TrnscTypeCd.송금:
      return i18n.t('remittance');
    case TrnscTypeCd.결제:
      return i18n.t('payment');
    case TrnscTypeCd.충전:
      return i18n.t('topUp');
    case TrnscTypeCd.전환:
      return i18n.t('conv');
    case TrnscTypeCd.전환입금:
      return i18n.t('convertToToken');
    case TrnscTypeCd.예금전환:
      return i18n.t('convertToDeposit');
    default:
      return '';
  }
};
